<?php use Hls\Http\View as V; ?>
<?php if(!empty($error)): ?><div class="alert alert-error"><?= V::escape($error) ?></div><?php endif ?>
<section class="panel"><form method="post" action="<?= $this->url('/finance/payable-update') ?>" class="form-grid"><?= $this->csrf() ?><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><label>Supplier<select name="supplier_id" required><?php foreach($suppliers as $s): ?><option value="<?= (int)$s['id'] ?>" <?= (int)$s['id']===(int)$row['supplier_id']?'selected':'' ?>><?= V::escape($s['name']) ?></option><?php endforeach ?></select></label><label>Cabang<select name="branch_id" required><?php foreach($branches as $b): if($access->branch((int)$b['id'])): ?><option value="<?= (int)$b['id'] ?>" <?= (int)$b['id']===(int)$row['branch_id']?'selected':'' ?>><?= V::escape($b['code'].' - '.$b['name']) ?></option><?php endif; endforeach ?></select></label><label>Nomor tagihan<input name="bill_ref" value="<?= V::escape($row['bill_ref']) ?>" required></label><label>Tanggal<input type="date" name="bill_date" value="<?= V::escape($row['bill_date']) ?>" required></label><label>Jatuh tempo<input type="date" name="due_date" value="<?= V::escape((string)$row['due_date']) ?>"></label><div data-bill-items><?php foreach($items as $item): ?><div class="bill-item"><input name="description[]" value="<?= V::escape($item['description']) ?>" placeholder="Deskripsi" required><input name="quantity[]" type="number" min="0.001" step="0.001" value="<?= V::escape($item['quantity']) ?>" required><input name="unit_price[]" type="number" min="0" step="0.01" value="<?= V::escape($item['unit_price']) ?>" required><button type="button" data-remove-item>Hapus Item</button></div><?php endforeach ?></div><button type="button" data-add-item>+ Tambah Item</button><button class="button button-primary">Simpan Perubahan</button></form></section><a class="button" href="<?= $this->url('/finance/payable-detail?id='.(int)$row['id']) ?>">Kembali</a>